package org.humanjourney.core.mapfeature;
import java.util.*;
import java.nio.file.*;
import net.minecraft.data.*;
import net.minecraft.nbt.*;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.core.RegistryAccess;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraftforge.data.event.GatherDataEvent;
import net.minecraftforge.eventbus.api.bus.BusGroup;
import org.humanjourney.core.geography.GeographyRoles;
public final class FeatureSmoke {
 public static void register(BusGroup group){GatherDataEvent.getBus(group).addListener(e->e.getGenerator().addProvider(true,new DataProvider(){public String getName(){return "Human Journey map features native data checks";}public java.util.concurrent.CompletableFuture<?> run(CachedOutput out){return java.util.concurrent.CompletableFuture.runAsync(FeatureSmoke::verify);}}));}
 private static void check(boolean c,String reason){if(!c)throw new IllegalStateException("Map features: "+reason);}
 private static void verify(){try{String json="{\"schema_version\":1,\"id\":\"synthetic_river\",\"label\":\"Synthetic River\",\"feature_type\":\"river\",\"dimension\":\"minecraft:overworld\",\"geometry\":{\"type\":\"polyline\",\"points\":[[0,0],[100,0]]}}";var data=FeatureCatalog.prepare(List.of(new FeatureCatalog.Source("test:one","synthetic",json),new FeatureCatalog.Source("test:hidden","synthetic",json.replace("synthetic_river","hidden_river").replace("Synthetic River","UNDISCOVERED_FEATURE_SECRET").replace("[0,0],[100,0]","[1000,0],[1100,0]"))));var saved=new SavedFeatures();saved.discover(new GeographyRoles(true,true,false),data,"minecraft:overworld",50,7);saved.mark("removed_feature");var tag=(CompoundTag)SavedFeatures.CODEC.encodeStart(NbtOps.INSTANCE,saved).getOrThrow();var path=Path.of("map-feature-native-check.dat");NbtIo.writeCompressed(tag,path);var restored=SavedFeatures.CODEC.parse(NbtOps.INSTANCE,NbtIo.readCompressed(path,NbtAccounter.unlimitedHeap())).getOrThrow();Files.delete(path);check(saved.snapshot().equals(restored.snapshot()),"independent native SavedData/stale ID round trip");var projected=FeatureCatalog.project(data,restored.snapshot().ids());check(projected.size()==1,"only known current geometry");var client=new ClientFeatureState();for(var f:FeaturePackets.frames(new FeaturePackets.Header(UUID.randomUUID(),1,saved.snapshot().revision(),1),FeaturePackets.Mode.FULL,0,projected.values(),List.of())){var buffer=new RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),RegistryAccess.fromRegistryOfRegistries(BuiltInRegistries.REGISTRY));try{FeaturePackets.CODEC.encode(buffer,f);check(buffer.readableBytes()<=FeaturePackets.MAX_BYTES,"bounded native wire");String raw=buffer.toString(0,buffer.writerIndex(),java.nio.charset.StandardCharsets.UTF_8);check(!raw.contains("UNDISCOVERED_FEATURE_SECRET")&&!raw.contains("discovery_radius"),"no hidden labels or server radius");client.accept(FeaturePackets.CODEC.decode(buffer));}finally{buffer.release();}}check(client.snapshot().features().equals(projected),"native codec client mirror");check(client.snapshot().index().hover("minecraft:overworld",50,1,5).feature()!=null,"segment-middle hover");check(FeatureSmoke.class.getClassLoader().getResource("xaero/map/gui/GuiMap.class")==null,"Xaero absent from common data runtime");com.mojang.logging.LogUtils.getLogger().info("[HJ Core] MAP_FEATURE_SMOKE_OK: independent compressed NBT/stale IDs, proximity, discovered-only bounded native codec/privacy and client index; no world/player/client created");}catch(Exception error){throw new IllegalStateException("Map feature native checks failed",error);}}
 private FeatureSmoke(){}
}
